export const getCreateInterventionUrl = (params?: CreateInterventionParams) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : stringifyQueryParam(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/api/v2/analytics/teacher/interventions?${stringifiedParams}`
    : `/api/v2/analytics/teacher/interventions`
}

/**
 * Retry-safe with `Idempotency-Key`: a replay returns the stored 201, a
 * different body under the same key is a 422.
 * @summary Record an intervention; the learner's latest risk score is captured as
`risk_score_before`.
 */
export const createIntervention = async (
  createInterventionRequest: CreateInterventionRequest,
  params?: CreateInterventionParams,
  options?: Parameters<typeof orvalMutator>[1],
): Promise<Intervention> => {
  const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, entry => Array.from(entry) as [string, string]),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return orvalMutator<Intervention>(
    getCreateInterventionUrl(params),
    {
      ...options,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
      body: JSON.stringify(createInterventionRequest),
    },
    Intervention,
  )
}

export const getCreateInterventionMutationKey = () => ['createIntervention'] as const

export const getCreateInterventionMutationOptions = <TError = ErrorType<Problem>, TContext = unknown>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createIntervention>>,
    TError,
    CreateInterventionMutationVariables,
    TContext
  >
  request?: SecondParameter<typeof orvalMutator>
}): UseMutationOptions<
  Awaited<ReturnType<typeof createIntervention>>,
  TError,
  CreateInterventionMutationVariables,
  TContext
> => {
  const mutationKey = getCreateInterventionMutationKey()
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined }

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createIntervention>>,
    CreateInterventionMutationVariables
  > = props => {
    const { data, params } = props ?? {}

    return createIntervention(data, params, requestOptions)
  }

  return { mutationFn, ...mutationOptions }
}

